      "tool": "sql",
      "query": "SELECT order_id, amount, vat, total, synced_at FROM ledger WHERE ROUND(total, 2) != ROUND(amount + vat, 2) OR ROUND(vat, 2) != ROUND(amount * 0.15, 2) ORDER BY synced_at ASC LIMIT 1",
      "why": "Determine the earliest occurrence of a ledger violation to see if it correlates with any external event or data change."
    },
    {
      "tool": "sql",
      "query": "SELECT i.order_id, i.amount, i.vat, i.total, l.amount as ledger_amount, l.vat as ledger_vat, l.total as ledger_total FROM invoices i JOIN ledger l ON i.order_id = l.order_id WHERE ROUND(l.total, 2) != ROUND(l.amount + l.vat, 2) OR ROUND(l.vat, 2) != ROUND(l.amount * 0.15, 2)",
      "why": "Compare the violating ledger rows with the source invoices to determine if the corruption originated during sync (ledger transformation error) or if the invoice data itself is invalid."
    }
  ],
  "hypotheses": [],
  "summary": "Investigating the timing and source of ledger integrity violations to distinguish between a sync-job fault and bad invoice data."
}
